// Ovaj fajl se pokrece pri svakoj objavi (vidi "build" u package.json).
// Upisuje najnovije fajlove aplikacije na pravo mesto u src/, pa nije bitno
// kako su stigli na GitHub. Ne menjaj ga rucno.
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname } from 'node:path'

const FILES = [
  ['src/components/AboutApp.jsx', ''],
  ['src/components/AnnouncementAdmin.jsx', ''],
  ['src/components/AnnouncementGate.jsx', ''],
  ['src/components/AnnouncementList.jsx', ''],
  ['src/components/Celebration.jsx', ''],
  ['src/components/CompareShifts.jsx', ''],
  ['src/components/Layout.jsx', ''],
  ['src/components/ReportListItem.jsx', ''],
  ['src/lib/about.js', ''],
  ['src/lib/announcements.js', ''],
  ['src/pages/AdminDashboard.jsx', ''],
  ['src/pages/AdminWorkers.jsx', ''],
  ['src/pages/Profile.jsx', ''],
  ['src/components/AnnouncementPopup.jsx', ''],
  ['src/lib/earnings.js', ''],
  ['src/components/AvatarCropper.jsx', ''],
  ['src/components/Avatar.jsx', ''],
  ['src/lib/avatars.js', ''],
  ['src/pages/ReportDetail.jsx', ''],
  ['src/pages/NewReport.jsx', '']
]

for (const [path, b64] of FILES) {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, Buffer.from(b64, 'base64'))
}
console.log('update.mjs: upisano ' + FILES.length + ' fajlova u src/')